import{_ as l,o as e,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS Jewel -- PMStore","description":"","frontmatter":{"title":"CDS Jewel -- PMStore","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","OSD","存储性能","内存映射","非易失性存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_PMStore.md","filePath":"posts/2015/CDS_Jewel_--_PMStore.md","lastUpdated":1780459816000}'),s={name:"posts/2015/CDS_Jewel_--_PMStore.md"};function i(a,t,p,n,_,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： P.M. Store 新型 OSD 后端方案讨论</p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Lucas, Nora, Bob, 等</p><p><strong>会议内容</strong>：</p><p><strong>1. 项目背景与目标</strong></p><ul><li>Lucas 和 Nora 介绍了 P.M. Store，这是一个针对非易失性存储（如 SSD）的实验性 OSD 后端。</li><li>该方案使用开源 p.m. 库，旨在提高存储性能，同时保持与现有 Ceph 代码库的兼容性。</li></ul><p><strong>2. 技术方案</strong></p><ul><li>使用内存映射文件存储对象，以固定大小的块处理碎片化。</li><li>对象包含指向块的 ID 和读写方法的向量，通过内存映射文件进行读写操作。</li><li>初步实现已完成，并计划开源。</li></ul><p><strong>3. 挑战与解决方案</strong></p><ul><li>正在解决边缘情况，并进行生命周期测试。</li><li>优化键序列化，使用事务性用户空间块设备进行目录读写。</li><li>对象和集合的索引存储在内存中，启动时从每个块的元数据重建。</li></ul><p><strong>4. 性能与测试</strong></p><ul><li>讨论了 4TB OSD 磁盘扫描所需时间的问题。</li><li>讨论了将元数据持久化存储在磁盘上的可能性，以及优化零拷贝操作。</li></ul><p><strong>5. 后续计划</strong></p><ul><li>Lucas 将在 GitHub 上开源 P.M. Store 代码，并邀请大家测试。</li><li>讨论了可能的优化，例如异步读写接口和改进的锁定机制。</li></ul><p><strong>6. 其他讨论</strong></p><ul><li>讨论了对象存储接口的回调机制，以及是否支持异步读写。</li><li>讨论了扩展地址顺序阶段，以支持同步和异步版本。</li></ul><p><strong>会议结论</strong>：</p><ul><li>P.M. Store 是一个有潜力的项目，有望提高 Ceph 的存储性能。</li><li>需要进一步优化和测试，以提高性能和稳定性。</li><li>Lucas 将开源代码，并邀请大家参与测试和讨论。</li></ul>',19)])])}const c=l(s,[["render",i]]);export{g as __pageData,c as default};
